using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading.Tasks;using System.Reflection;using System.Windows;using System.Windows.Controls;using CnDirect;
namespace BrowserManager {
 public static class FormalTests {
  class Handle:IDisposable{public int Closed;public void Dispose(){Closed++;}}
  class Backend:WebSessionBackend{
   public Target[] Windows=new Target[0];public int Prepared,Attached;public bool Fail;public Handle Handle=new Handle();public Target Selected;public LoginRoute Choice;
   public Task PrepareBrowser(LoginRoute choice,System.Threading.CancellationToken cancel){Prepared++;Choice=choice;return Task.FromResult(0);}public Target[] Targets(){return Windows;}public Task<IDisposable> Attach(Target target,System.Threading.CancellationToken cancel){Attached++;Selected=target;if(Fail)throw new InvalidOperationException("FAKE_CHANGED");return Task.FromResult((IDisposable)Handle);}
  }
  static bool Reject(Func<Task<PreparedWebSession>> work){try{work().GetAwaiter().GetResult();return false;}catch{return true;}}
  static IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var d in Walk(child))yield return d;}
  static T Field<T>(MainWindow window,string name){return (T)typeof(MainWindow).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(window);}
  public static void Run(string report){var rows=new List<string>();Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);rows.Add("通过："+label);};var a=Account.New("虚构国服账号","CN");var t=new Target{Pid=42,Started=99,Title="虚构登录窗口"};
   foreach(string mode in new[]{"webview2","chrome","edge"}){a.LoginBrowser=mode;var b=new Backend{Windows=new[]{t}};using(var result=WebSessionStarter.Existing(b,new LoginRoute(a)).GetAwaiter().GetResult()){check(result.Choice.Mode==mode&&result.Choice.Id==a.Id&&b.Selected==t&&b.Prepared==1&&b.Attached==1,mode+" 绑定所选账号并只准备唯一待登录窗口");}check(b.Handle.Closed==1,mode+" 取消准备后释放接管句柄");}
   var empty=new Backend();check(Reject(()=>WebSessionStarter.Existing(empty,new LoginRoute(a)))&&empty.Prepared==0&&empty.Attached==0,"无待登录窗口时停止，不启动或切换任何客户端");var multiple=new Backend{Windows=new[]{t,new Target{Pid=43,Started=100}}};check(Reject(()=>WebSessionStarter.Existing(multiple,new LoginRoute(a)))&&multiple.Attached==0,"多个窗口时不猜测，交给用户指定");var changed=new Backend{Windows=new[]{t},Fail=true};check(Reject(()=>WebSessionStarter.Existing(changed,new LoginRoute(a)))&&changed.Attached==1,"窗口变化时停止，不改选其他客户端");
   check(typeof(MainWindow).GetMethod("StartNative",BindingFlags.NonPublic|BindingFlags.Instance)==null&&typeof(MainWindow).GetMethod("RegisterNative",BindingFlags.NonPublic|BindingFlags.Instance)==null,"正式版移除客户端一键登录与登记代码");check(typeof(NativeLogin).GetMethod("Start")==null&&typeof(NativeLogin).GetMethod("SelectedConfig")==null,"不包含旧整份配置启动或快照恢复入口");
   var w=new MainWindow(true,"CN");try{var labels=Walk((DependencyObject)w.Content).OfType<Button>().Select(x=>Convert.ToString(x.Content)).ToArray();check(!labels.Any(x=>x.Contains("恢复 A")||x.Contains("恢复 B")||x.Contains("另开")),"没有旧快照恢复或免认证多开入口");check(Field<Expander>(w,"cnExperiment").IsExpanded&&!Field<Button>(w,"cnExperimentalStart").IsEnabled,"国服实验展开，未记住账号不能启动");check(labels.Contains("网页登录")&&labels.Contains("打开战网"),"国服主要入口为网页登录和打开战网");check(!Field<Expander>(w,"options").IsExpanded&&!Field<Expander>(w,"route").IsExpanded,"浏览器选项及窗口选择默认折叠");check(Field<Border>(w,"globalCard").Visibility==Visibility.Collapsed,"国服页面不混入外服登录说明");}finally{w.Close();}
   var g=new MainWindow(true,"GLOBAL");try{check(Field<Border>(g,"browserCard").Visibility==Visibility.Collapsed&&Field<Border>(g,"globalCard").Visibility==Visibility.Visible,"外服保留独立账号备忘及官方客户端入口");check(Field<Expander>(g,"cnExperiment").Visibility==Visibility.Collapsed,"外服页面不显示国服实验入口");}finally{g.Close();}
   string parent=Path.GetDirectoryName(Path.GetFullPath(report)),root=Path.Combine(parent,"formal-migration-"+Guid.NewGuid().ToString("N"));try{string prior=Path.Combine(root,"战网账号管家-v0.13.0"),current=Path.Combine(root,"战网账号管家-v1.0.0");Directory.CreateDirectory(current);var data=Store.Initial();data.Accounts.Add(a);new Store(prior).Save(data);check(Store.ResolveHome(current)==prior,"正式版沿用 v0.13.0 资料目录，保持账号及浏览器路径");}finally{string full=Path.GetFullPath(root);if(full.StartsWith(parent.TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(full).StartsWith("formal-migration-",StringComparison.Ordinal))Directory.Delete(full,true);}
   rows.Add("合计 "+rows.Count+" 项通过。仅用虚构窗口与资料；不操作真实认证、客户端配置或实际账号。");File.WriteAllLines(report,rows,new UTF8Encoding(true));
  }
 }
}
